// @vitest-environment node

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import {
  GatewayRecoveryController,
  type GatewayRecoveryControllerOptions,
} from './recovery-controller';
import { GATEWAY_LIVENESS_DEADLINE_MS } from './recovery-budget';

function createController(overrides: Partial<GatewayRecoveryControllerOptions> = {}) {
  const requestDeadlineProbe = vi.fn().mockResolvedValue(undefined);
  const requestOwnedProcessEscalation = vi.fn();
  const requestExternalTransportReconnect = vi.fn();
  const controller = new GatewayRecoveryController({
    isExternallyManaged: () => false,
    requestDeadlineProbe,
    requestOwnedProcessEscalation,
    requestExternalTransportReconnect,
    ...overrides,
  });

  return {
    controller,
    requestDeadlineProbe,
    requestOwnedProcessEscalation,
    requestExternalTransportReconnect,
  };
}

describe('GatewayRecoveryController', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-03-19T00:00:00.000Z'));
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it('schedules one deadline probe from the last trusted liveness signal', async () => {
    const { controller, requestDeadlineProbe } = createController();

    controller.start();
    expect(controller.getSnapshot()).toMatchObject({
      state: 'healthy',
      lastAliveAt: Date.now(),
      deadlineAt: Date.now() + GATEWAY_LIVENESS_DEADLINE_MS,
    });

    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS - 1);
    expect(requestDeadlineProbe).not.toHaveBeenCalled();

    await vi.advanceTimersByTimeAsync(1);
    expect(requestDeadlineProbe).toHaveBeenCalledTimes(1);
    controller.stop();
  });

  it('resets the deadline for every trusted liveness signal', async () => {
    const { controller, requestDeadlineProbe } = createController();

    controller.start();
    await vi.advanceTimersByTimeAsync(60_000);
    controller.recordAlive();

    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS - 1);
    expect(requestDeadlineProbe).not.toHaveBeenCalled();

    await vi.advanceTimersByTimeAsync(1);
    expect(requestDeadlineProbe).toHaveBeenCalledTimes(1);
    controller.stop();
  });

  it('returns to healthy after a successful deadline probe', async () => {
    const { controller } = createController();

    controller.start();
    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS);

    expect(controller.getSnapshot()).toMatchObject({
      state: 'healthy',
      lastAliveAt: Date.now(),
      lastDeadlineProbeAt: Date.now(),
      lastDeadlineProbeResult: 'succeeded',
    });
    controller.stop();
  });

  it('requests exactly one owned-process escalation after a failed deadline probe', async () => {
    const error = new Error('system-presence timed out');
    const {
      controller,
      requestOwnedProcessEscalation,
    } = createController({ requestDeadlineProbe: vi.fn().mockRejectedValue(error) });

    controller.start();
    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS);

    expect(requestOwnedProcessEscalation).toHaveBeenCalledTimes(1);
    expect(requestOwnedProcessEscalation).toHaveBeenCalledWith('deadline-probe-timeout');
    expect(controller.getSnapshot()).toMatchObject({
      state: 'restart-executing',
      lastDeadlineProbeResult: 'failed',
      lastDeadlineProbeError: 'deadline-probe-timeout',
      escalationReason: 'deadline-probe-timeout',
      externallyManaged: false,
    });

    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS);
    expect(requestOwnedProcessEscalation).toHaveBeenCalledTimes(1);
    controller.stop();
  });

  it('defers owned-process escalation during compaction and resumes it when compaction ends', async () => {
    let compactionActive = true;
    const {
      controller,
      requestOwnedProcessEscalation,
    } = createController({
      isCompactionActive: () => compactionActive,
      requestDeadlineProbe: vi.fn().mockRejectedValue(new Error('system-presence timed out')),
    });

    controller.start();
    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS);

    expect(requestOwnedProcessEscalation).not.toHaveBeenCalled();
    expect(controller.getSnapshot().state).toBe('restart-pending');

    compactionActive = false;
    controller.resumeDeferredEscalation();

    expect(requestOwnedProcessEscalation).toHaveBeenCalledWith('deadline-probe-timeout');
    expect(controller.getSnapshot().state).toBe('restart-executing');
    controller.stop();
  });

  it('cancels a deferred escalation when trusted liveness returns during compaction', async () => {
    let compactionActive = true;
    const {
      controller,
      requestOwnedProcessEscalation,
    } = createController({
      isCompactionActive: () => compactionActive,
      requestDeadlineProbe: vi.fn().mockRejectedValue(new Error('system-presence timed out')),
    });

    controller.start();
    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS);
    controller.recordAlive();
    compactionActive = false;
    controller.resumeDeferredEscalation();

    expect(requestOwnedProcessEscalation).not.toHaveBeenCalled();
    expect(controller.getSnapshot().state).toBe('healthy');
    controller.stop();
  });

  it('categorizes token-bearing probe errors without exposing them in diagnostics or callbacks', async () => {
    const secret = 'sk-live-very-secret-token-value';
    const {
      controller,
      requestOwnedProcessEscalation,
    } = createController({
      requestDeadlineProbe: vi.fn().mockRejectedValue(
        new Error(`RPC timeout: system-presence authorization=${secret}`),
      ),
    });

    controller.start();
    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS);

    const snapshot = controller.getSnapshot();
    expect(snapshot.lastDeadlineProbeError).toBe('deadline-probe-timeout');
    expect(snapshot.escalationReason).toBe('deadline-probe-timeout');
    expect(JSON.stringify(snapshot)).not.toContain(secret);
    expect(requestOwnedProcessEscalation).toHaveBeenCalledWith('deadline-probe-timeout');
    controller.stop();
  });

  it('requests only a transport reconnect for an external Gateway after a failed probe', async () => {
    const {
      controller,
      requestExternalTransportReconnect,
      requestOwnedProcessEscalation,
    } = createController({
      isExternallyManaged: () => true,
      requestDeadlineProbe: vi.fn().mockRejectedValue(new Error('system-presence timed out')),
    });

    controller.start();
    await vi.advanceTimersByTimeAsync(GATEWAY_LIVENESS_DEADLINE_MS);

    expect(requestExternalTransportReconnect).toHaveBeenCalledTimes(1);
    expect(requestExternalTransportReconnect).toHaveBeenCalledWith('deadline-probe-timeout');
    expect(requestOwnedProcessEscalation).not.toHaveBeenCalled();
    expect(controller.getSnapshot()).toMatchObject({
      state: 'external-unavailable',
      externallyManaged: true,
    });
    controller.stop();
  });

  it('ignores an old deadline probe completion after newer liveness', async () => {
    let resolveProbe: (() => void) | undefined;
    const probe = new Promise<void>((resolve) => {
      resolveProbe = resolve;
    });
    const { controller, requestOwnedProcessEscalation } = createController({
      requestDeadlineProbe: vi.fn().mockReturnValue(probe),
    });

    controller.start();
    vi.advanceTimersByTime(GATEWAY_LIVENESS_DEADLINE_MS);
    await Promise.resolve();
    expect(controller.getSnapshot().state).toBe('verifying');

    controller.recordAlive();
    resolveProbe?.();
    await Promise.resolve();
    await Promise.resolve();

    expect(requestOwnedProcessEscalation).not.toHaveBeenCalled();
    expect(controller.getSnapshot()).toMatchObject({
      state: 'healthy',
      lastAliveAt: Date.now(),
      lastDeadlineProbeResult: undefined,
    });
    controller.stop();
  });
});

import { describe, expect, it } from 'bun:test'
import { Linter } from 'eslint'
import { createRequire } from 'node:module'

const require = createRequire(import.meta.url)
const rule = require('../no-hardcoded-z-index.cjs')

function runRule(code: string) {
  const linter = new Linter({ configType: 'eslintrc' })
  linter.defineRule('craft-styles/no-hardcoded-z-index', rule)

  return linter.verify(code, {
    parserOptions: {
      ecmaVersion: 'latest',
      sourceType: 'module',
    },
    rules: {
      'craft-styles/no-hardcoded-z-index': 'error',
    },
  })
}

describe('no-hardcoded-z-index (electron)', () => {
  it('flags hardcoded default in destructured props', () => {
    const messages = runRule('function Comp({ zIndex = 50 }) { return zIndex }')
    expect(messages.length).toBe(1)
    expect(messages[0]?.message).toContain('Avoid hardcoded zIndex values')
  })

  it('flags hardcoded default in object destructuring', () => {
    const messages = runRule('const { zIndex = 50 } = props')
    expect(messages.length).toBe(1)
  })

  it('allows token-based zIndex default values', () => {
    const messages = runRule("const { zIndex = 'var(--z-floating-menu, 400)' } = props")
    expect(messages.length).toBe(0)
  })

  it('continues to flag hardcoded style zIndex literals', () => {
    const messages = runRule('const style = { zIndex: 400 }')
    expect(messages.length).toBe(1)
  })
})

import { execFile } from 'node:child_process';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

import { build } from 'esbuild';
import { expect, test } from 'vitest';

import { OPENCLAW_REPAIR_SNAPSHOT_MANIFEST, OpenClawRepairPhase } from '../../shared/openclawEngine/repair';
import { removeTreeNoFollowSync } from './removeTreeNoFollow';

// Exercise the app's Electron fs bindings as well as Node's. On Windows these
// are actual junctions, including a target removed by an installer upgrade.
test('Electron snapshots valid and dangling generated junctions without creating links', async () => {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'lobster-repair-electron-')));
  const require = createRequire(import.meta.url);
  try {
    await build({
      entryPoints: [fileURLToPath(new URL('./openclawCompatibilityRepairCore.ts', import.meta.url))],
      outfile: path.join(root, 'owner.cjs'), bundle: true, platform: 'node', format: 'cjs', logLevel: 'silent',
    });
    const request = {
      stateDir: path.join(root, 'state'), configPath: path.join(root, 'state', 'openclaw.json'),
      backupDir: path.join(root, 'backup'), phase: OpenClawRepairPhase.Snapshot,
    };
    fs.writeFileSync(path.join(root, 'request.json'), JSON.stringify(request));
    const script = path.join(root, 'exercise.cjs');
    fs.writeFileSync(script, `
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const options = require('./request.json');
const { repairOpenClawCompatibility } = require('./owner.cjs');
(async () => {
  const skills = path.join(options.stateDir, 'plugin-skills');
  const external = path.join(__dirname, 'external-plugin');
  for (const dir of [skills, external, options.backupDir]) fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(external, 'SKILL.md'), 'external content');
  fs.writeFileSync(path.join(skills, 'user-file.txt'), 'user content');
  const links = [path.join(skills, 'valid'), path.join(skills, 'dangling')];
  fs.symlinkSync(external, links[0], 'junction');
  fs.symlinkSync(path.join(__dirname, 'removed-installation'), links[1], 'junction');
  const targets = links.map(link => fs.readlinkSync(link));
  fs.symlinkSync = () => { throw Object.assign(new Error('EPERM: symlink creation denied'), { code: 'EPERM' }); };
  const report = await repairOpenClawCompatibility(options, { withLock: async run => run() });
  assert.equal(report.success, true, report.error);
  assert.deepEqual(links.map(link => fs.readlinkSync(link)), targets);
  assert.equal(fs.readFileSync(path.join(external, 'SKILL.md'), 'utf8'), 'external content');
  assert.equal(fs.readFileSync(path.join(options.backupDir, 'original', 'plugin-skills', 'user-file.txt'), 'utf8'), 'user content');
  console.log(JSON.stringify({ electron: process.versions.electron, platform: process.platform, report }));
})().catch(error => { console.error(error); process.exitCode = 1; });
`);
    const result = await promisify(execFile)(require('electron') as string, [script], {
      env: { ...process.env, ELECTRON_RUN_AS_NODE: '1' }, windowsHide: true, timeout: 20_000,
    });
    expect(JSON.parse(result.stdout)).toMatchObject({ electron: expect.any(String), platform: process.platform,
      report: { success: true, phase: OpenClawRepairPhase.Snapshot } });
    const manifest = JSON.parse(fs.readFileSync(path.join(request.backupDir, OPENCLAW_REPAIR_SNAPSHOT_MANIFEST), 'utf8'));
    expect(manifest.generatedPluginSkillLinks).toHaveLength(2);
  } finally {
    removeTreeNoFollowSync(root);
  }
}, 30_000);

import { execFile } from 'node:child_process';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

import { build } from 'esbuild';
import { expect, test } from 'vitest';

import { removeTreeNoFollowSync } from './removeTreeNoFollow';

// Plain Node's recursive rm does not reproduce Electron's Windows junction bug.
// Compile the production owner and execute it with the app's actual Electron.
test.runIf(process.platform === 'win32')('Electron cleanup preserves a junction target and handles dangling links', async () => {
  const root = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'lobsterai-junction-electron-')));
  const require = createRequire(import.meta.url);
  const electronPath = require('electron') as string;
  const ownerPath = path.join(root, 'owner.cjs');
  try {
    await build({
      entryPoints: [fileURLToPath(new URL('./openclawLocalExtensions.ts', import.meta.url))],
      outfile: ownerPath,
      bundle: true,
      platform: 'node',
      format: 'cjs',
      external: ['electron'],
      logLevel: 'silent',
    });
    const scriptPath = path.join(root, 'exercise.cjs');
    fs.writeFileSync(scriptPath, `
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const Module = require('node:module');
const root = __dirname;
const load = Module._load;
Module._load = function(id, ...args) {
  if (id === 'electron') return { app: { isPackaged: false, getAppPath: () => root } };
  return load.call(this, id, ...args);
};
const { cleanupStaleThirdPartyPluginsFromBundledDir } = require('./owner.cjs');
fs.writeFileSync(path.join(root, 'package.json'), JSON.stringify({ openclaw: { plugins: [] } }));
const runtime = path.join(root, 'runtime');
const target = path.join(root, 'host-runtime');
const stale = path.join(runtime, 'extensions', 'test-plugin');
const link = path.join(stale, 'node_modules', 'openclaw');
for (const dir of [path.dirname(link), target]) fs.mkdirSync(dir, { recursive: true });
const marker = path.join(target, 'worker.js');
fs.writeFileSync(marker, 'host runtime worker');
fs.symlinkSync(target, link, 'junction');
assert(fs.lstatSync(link).isSymbolicLink());
assert.equal(fs.realpathSync(link), target);
// Both the deletion root and its link target are newly-created fixture children.
for (const dir of [stale, target]) {
  const relative = path.relative(root, path.resolve(dir));
  assert(relative && !relative.startsWith('..') && !path.isAbsolute(relative));
}
assert.deepEqual(cleanupStaleThirdPartyPluginsFromBundledDir(runtime, ['test-plugin']), ['test-plugin']);
assert.equal(fs.existsSync(stale), false);
assert.equal(fs.readFileSync(marker, 'utf8'), 'host runtime worker');
fs.symlinkSync(path.join(root, 'absent'), stale, 'junction');
assert.deepEqual(cleanupStaleThirdPartyPluginsFromBundledDir(runtime, ['test-plugin']), ['test-plugin']);
assert.equal(fs.lstatSync(stale, { throwIfNoEntry: false }), undefined);
console.log(JSON.stringify({ electron: process.versions.electron, workerPreserved: true }));
`);
    const result = await promisify(execFile)(electronPath, [scriptPath], {
      env: { ...process.env, ELECTRON_RUN_AS_NODE: '1' },
      windowsHide: true,
      timeout: 20_000,
    });
    expect(JSON.parse(result.stdout)).toMatchObject({ electron: expect.any(String), workerPreserved: true });
  } finally {
    // Teardown must also stop at any link left by a failed regression.
    removeTreeNoFollowSync(root);
  }
}, 30_000);
